  'settings.ai.quotaNote': 'El uso de IA en Writers Hoard cuenta contra tu cuota de suscripción Max. Haiku consume menos cuota que Sonnet.',
  'settings.bridge.title': 'Puente IA',
  'settings.bridge.connect.title': 'Conectar una IA externa a Writers Hoard',
  'settings.bridge.connect.intro': 'Configura la conexión una vez y pasa el mensaje de inicio a tu asistente para que conozca tus proyectos y sepa usar las herramientas de la app.',
  'settings.bridge.connect.client': '¿Desde dónde vas a usar la IA?',
  'settings.bridge.connect.web': 'chat web',
  'settings.bridge.connect.webNote': 'Pegar un mensaje o la dirección local en un chat web no establece una conexión. Este puente funciona con clientes MCP locales: Claude Desktop, Codex o Gemini CLI. Los conectores web necesitan una integración remota compatible, que esta app no publica. El mensaje de abajo sirve después de configurar un cliente compatible.',
  'settings.bridge.connect.prepare': 'Activa el Puente IA y mantén Writers Hoard abierto. Instala Node.js si no lo tienes; el cliente debe poder ejecutar node (o sustituye command por la ruta completa a node.exe). Empieza con la escritura desactivada.',
  'settings.bridge.connect.claude': 'En Claude Desktop, abre Ajustes → Desarrollador → Editar configuración (claude_desktop_config.json). Añade la entrada writers-hoard dentro de mcpServers; conserva tus otros servidores y ajustes.',
  'settings.bridge.connect.codex': 'Añade el bloque TOML a ~/.codex/config.toml (en Windows, .codex dentro de tu carpeta de usuario). Si ya existe mcp_servers.writers-hoard, actualiza ese bloque en lugar de duplicarlo.',
  'settings.bridge.connect.gemini': 'Añade la entrada writers-hoard a mcpServers en ~/.gemini/settings.json (en Windows, .gemini dentro de tu carpeta de usuario). Conserva tus otros servidores y ajustes.',
  'settings.bridge.connect.restart': 'Reinicia el cliente y comprueba que aparece writers-hoard entre sus herramientas MCP (en Codex y Gemini CLI: /mcp). Después pega el mensaje de inicio en una conversación nueva. Si cambias permisos de escritura, vuelve a conectar el cliente para actualizar sus herramientas.',
  'settings.bridge.connect.docs': 'Ver instrucciones oficiales del cliente',
