  'writings.recoveryConflict.title': 'Borrador sin guardar de una sesión anterior',
  'writings.recoveryConflict.message': 'Este capítulo cambió en otro sitio mientras un borrador sin guardar seguía esperando: el copiloto, un reemplazo en todo el proyecto o una copia de seguridad restaurada.\n\nLo que está abierto es el capítulo tal como está guardado en disco. El borrador ha quedado en el historial de versiones de este capítulo en cualquier caso, así que no se pierde nada elijas lo que elijas.',
