  'writings.externalChange.title': 'Este capítulo cambió en otro sitio',
  'writings.externalChange.message': 'Algo que no es este editor reescribió el capítulo mientras trabajabas en él: el copiloto, un cliente externo, un reemplazo en todo el proyecto o una copia de seguridad restaurada. No se ha sobrescrito nada: el tuyo tiene {mine} palabras y la versión en disco tiene {theirs}. Elijas la que elijas, la otra queda en el historial de versiones de este capítulo.',
